 const string D="Assets/Lighthouse_Authored";public const string Scene="Assets/Scenes/Lighthouse_Coast_ArtBenchmark_V01.unity";
 static List<string> manifest=new List<string>();
 static Material Material(string n,Color col){string p=D+"/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,p);}m.color=col;string low=n.ToLowerInvariant();if(low.Contains("sand")||low.Contains("meadow")||low.Contains("grass")||low.Contains("limestone")||low.Contains("footpath")){m.shader=Shader.Find("Coast/Painted");m.SetTexture("_Atlas",AssetDatabase.LoadAssetAtPath<Texture2D>(D+"/PaintedSurfaceAtlas.png"));m.SetFloat("_Kind",low.Contains("footpath")?4:low.Contains("limestone")?2:low.Contains("grass")||low.Contains("meadow")?1:0);m.SetFloat("_Scale",low.Contains("limestone")?7:low.Contains("sand")?9:4.5f);m.color=low.Contains("grass")||low.Contains("meadow")?new Color(.80f,.91f,.72f):low.Contains("limestone")?new Color(.80f,.86f,.94f):new Color(.92f,.94f,.91f);}m.SetFloat("_Glossiness",.05f);m.enableInstancing=true;return m;}
 static Bounds Bounds(GameObject g){var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
 static GameObject Asset(string file,Vector3 at,float height,float rotation=0){string path=AssetDatabase.FindAssets(Path.GetFileNameWithoutExtension(file)+" t:Model",new[]{"Assets/Art/External"}).Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>Path.GetFileName(p)==file);if(path==null){Debug.LogWarning("Missing candidate "+file);return null;}var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path));g.transform.rotation=Quaternion.Euler(0,rotation,0);var b=Bounds(g);g.transform.localScale*=height/b.size.y;b=Bounds(g);g.transform.position+=at-new Vector3(b.center.x,b.min.y,b.center.z);manifest.Add(path+"\t"+at+"\t"+height);return g;}
 static void Shot(Camera c,string name){var r=new RenderTexture(1800,1125,24);c.targetTexture=r;c.Render();RenderTexture.active=r;var tex=new Texture2D(1800,1125,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1800,1125),0,0);tex.Apply();File.WriteAllBytes("Docs/Lighthouse_Authored/"+name+".png",tex.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(r);}
