 public static void Build(){AssetDatabase.Refresh();manifest.Clear();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var path=D+"/CoastArchitecture.fbx";var imp=(ModelImporter)AssetImporter.GetAtPath(path);imp.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;imp.SaveAndReimport();var root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path));root.name="Authored cliff and lighthouse assemblies";root.transform.localScale=new Vector3(-1,1,-1);
 var bakedRoot=new GameObject("Authored coast geometry");int meshIndex=0;
 foreach(var f in root.GetComponentsInChildren<MeshFilter>()){var go=new GameObject(f.name);go.transform.SetParent(bakedRoot.transform);var source=f.sharedMesh;var copy=UnityEngine.Object.Instantiate(source);copy.name=f.name;copy.vertices=source.vertices.Select(v=>f.transform.TransformPoint(v)).ToArray();if(f.transform.localToWorldMatrix.determinant<0){for(int sub=0;sub<source.subMeshCount;sub++){var indices=source.GetTriangles(sub);for(int k=0;k<indices.Length;k+=3){int t=indices[k];indices[k]=indices[k+2];indices[k+2]=t;}copy.SetTriangles(indices,sub);}}copy.RecalculateNormals();copy.RecalculateBounds();string mp=D+"/BakedMesh"+(meshIndex++)+".asset";AssetDatabase.DeleteAsset(mp);AssetDatabase.CreateAsset(copy,mp);go.AddComponent<MeshFilter>().sharedMesh=copy;go.AddComponent<MeshRenderer>().sharedMaterials=f.GetComponent<Renderer>().sharedMaterials;}
 UnityEngine.Object.DestroyImmediate(root);root=bakedRoot;

 foreach(var r in root.GetComponentsInChildren<Renderer>()){var mm=r.sharedMaterials;for(int i=0;i<mm.Length;i++){if(!mm[i])continue;string name=mm[i].name;var color=mm[i].HasProperty("_Color")?mm[i].color:Color.white;mm[i]=Material(name,color);}r.sharedMaterials=mm;}
 foreach(var f in root.GetComponentsInChildren<MeshFilter>()){if(f.name.Contains("guardrail")||f.name.Contains("seam")||f.name.Contains("spindle")||f.name.Contains("mullion"))continue;f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;}
 // Specific approved trees, each with authored position and scale. No random scattering.
 var trees=new[]{new Vector4(-17,3.6f,0,6.8f),new Vector4(18,3.6f,8,7.2f),new Vector4(-14,7.6f,17,7.5f),new Vector4(12,7.6f,19,6.2f),new Vector4(-9,12.4f,25,5.5f),new Vector4(9,12.4f,27,5.8f),new Vector4(-20,.32f,-9,5.2f),new Vector4(15,.32f,-10,5.8f)};
 for(int i=0;i<6;i++){var p=trees[i];var tree=Asset(i%2==0?"CommonTree_1.fbx":"CommonTree_2.fbx",new Vector3(p.x,p.y,p.z),p.w,i*37);tree.transform.localScale=Vector3.Scale(tree.transform.localScale,new Vector3(1.45f,1,1.45f));}
 // Grouped bushes: selected to frame the route, cliff corners and tower courtyard.
 var bushes=new[]{new Vector3(-15,3.6f,-2),new Vector3(-14,3.6f,-3),new Vector3(-16,3.6f,-.6f),new Vector3(16,3.6f,6),new Vector3(17,3.6f,7),new Vector3(15,3.6f,7),new Vector3(-13,7.6f,15),new Vector3(-12,7.6f,16),new Vector3(12,7.6f,17),new Vector3(11,7.6f,18),new Vector3(-8,12.4f,22),new Vector3(-8,12.4f,24),new Vector3(8,12.4f,25),new Vector3(7,12.4f,26),new Vector3(-17,.32f,-12),new Vector3(13,.32f,-9)};
 for(int i=0;i<bushes.Length;i++)Asset("Bush_Common_Flowers.fbx",bushes[i],i%3==0?1.2f:.85f,i*29);
 var sun=new GameObject("Soft warm coastal sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.18f;sun.color=new Color(1,.93f,.80f);sun.shadows=LightShadows.Soft;sun.shadowStrength=.72f;sun.transform.rotation=Quaternion.Euler(44,-38,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.63f,.77f,.92f);RenderSettings.ambientEquatorColor=new Color(.40f,.47f,.51f);RenderSettings.ambientGroundColor=new Color(.26f,.30f,.34f);QualitySettings.shadowDistance=150;QualitySettings.shadowResolution=ShadowResolution.VeryHigh;QualitySettings.antiAliasing=8;
 var sky=Material("Coastal sky",Color.white);sky.shader=Shader.Find("Skybox/Procedural");sky.SetFloat("_SunSize",.025f);sky.SetFloat("_AtmosphereThickness",.65f);sky.SetFloat("_Exposure",1.15f);sky.SetColor("_SkyTint",new Color(.50f,.50f,.50f));sky.SetColor("_GroundColor",new Color(.25f,.51f,.61f));RenderSettings.skybox=sky;RenderSettings.sun=sun;
 var water=new GameObject("Living turquoise bay");var mesh=new Mesh();mesh.vertices=new[]{new Vector3(-900,-.14f,-900),new Vector3(-900,-.14f,900),new Vector3(900,-.14f,-900),new Vector3(900,-.14f,900)};mesh.triangles=new[]{0,1,2,2,1,3};mesh.RecalculateNormals();AssetDatabase.DeleteAsset(D+"/OceanPlane.asset");AssetDatabase.CreateAsset(mesh,D+"/OceanPlane.asset");water.AddComponent<MeshFilter>().sharedMesh=mesh;var wm=Material("Turquoise bay",Color.white);wm.shader=Shader.Find("Coast/Water");water.AddComponent<MeshRenderer>().sharedMaterial=wm;
 var c=new GameObject("Game camera").AddComponent<Camera>();c.tag="MainCamera";c.nearClipPlane=.1f;c.farClipPlane=1600;c.fieldOfView=53;c.clearFlags=CameraClearFlags.Skybox;RenderSettings.fog=true;RenderSettings.fogColor=new Color(.48f,.73f,.82f);RenderSettings.fogMode=FogMode.Exponential;RenderSettings.fogDensity=.0015f;
 var pos=new[]{new Vector3(-35,25,-39),new Vector3(-11,3,-20),new Vector3(9,6,-5),new Vector3(-12,10,9),new Vector3(5,14,19),new Vector3(-10,15,21),new Vector3(-23,3,-14),new Vector3(-18,6,-3),new Vector3(-15,4,-5)};var look=new[]{new Vector3(0,9,8),new Vector3(3,6,4),new Vector3(-4,7,8),new Vector3(1,13,23),new Vector3(-2,19,25),new Vector3(-2,18,25),new Vector3(-8,2,-9),new Vector3(-6,5,2),new Vector3(-13,3.7f,-1)};for(int i=0;i<pos.Length;i++){c.transform.position=pos[i];c.transform.LookAt(look[i]);Shot(c,i.ToString("00"));}
 var player=new GameObject("Explorer");player.transform.position=new Vector3(-13,.5f,-16);var cc=player.AddComponent<CharacterController>();cc.height=1.75f;cc.center=Vector3.up*.875f;cc.radius=.3f;cc.slopeLimit=46;cc.stepOffset=.32f;var w=player.AddComponent<LighthouseWalker>();w.view=c;var actor=Asset("Superhero_Male_FullBody.fbx",player.transform.position,1.75f);if(actor)actor.transform.SetParent(player.transform,true);c.transform.position=player.transform.position+new Vector3(0,2.7f,-5);c.transform.LookAt(player.transform.position+Vector3.up);
 EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),Scene);File.WriteAllLines("Docs/Lighthouse_Authored/PLACED_ASSETS.tsv",manifest);AssetDatabase.SaveAssets();Debug.Log("AUTHORED_COAST_BUILT");}
